/**
 * The http binding: `ContextApi` over the Heed service, through a client typed from the API
 * contract (src/contract). It needs the contract's routes only, not its schemas (the service
 * validates), so it reads them from `contract.json`, generated by `npm run api:generate`.
 * Loaded on demand, so the first load of the app does not carry it.
 *
 * Changes carry two headers. `X-Heed-CSRF` is the session's token, read from `auth.session`
 * (the session cookie is HttpOnly, so the page cannot read it); a refused token is read again
 * once. `Idempotency-Key` names one intended change: the same request keeps its key until the
 * service gives a final answer, so a retry after a lost answer is applied once.
 */
import { createORPCClient } from '@orpc/client'
import type { AnyContractRouter, ContractRouterClient } from '@orpc/contract'
import { OpenAPILink } from '@orpc/openapi-client/fetch'
import type { UIMessageChunk } from 'ai'
import type { Contract } from '../../contract/index.ts'
import { refusals } from '../../contract/refusals.ts'
import { canonicalJson } from '../../domain/canonical.ts'
import routes from './contract.json' with { type: 'json' }
import {
  API_VERSION_HEADER,
  noteServiceVersion,
  outdatedSide,
  updateAdvice,
} from './api-version.ts'
import type { ContextApi, PersonalLists } from './client.ts'
import { ApiError, toApiError } from './errors.ts'

export type HttpApiOptions = {
  /** Absolute URL of the API, with its version prefix: `https://host/api/v1`. */
  baseUrl: string
  /** Favourites and recent items, which stay in the browser. */
  personal: PersonalLists
  fetch?: typeof globalThis.fetch
  /** Makes retry keys; tests pass a counter. */
  newKey?: () => string
}

type CallContext = { headers?: Record<string, string> }

/** 128 random bits as hex. Unlike `crypto.randomUUID`, it also works outside a secure context. */
export function randomKey(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(16))
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('')
}

/**
 * A moment as an ISO string. The tool list sends PostgreSQL's text form
 * (`2026-10-07 12:00:00.123456+00`), which only some browsers parse; anything else passes as is.
 */
export function isoMoment(text: string): string {
  const match = /^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2}(?:\.\d+)?)([+-]\d{2})(?::?(\d{2}))?$/.exec(
    text,
  )
  if (!match) return text
  const [, day, time, hours, minutes = '00'] = match
  return new Date(`${day}T${time}${hours}:${minutes}`).toISOString()
}

const withIsoMoment = <T extends { updatedAt: string }>(tool: T): T => ({
  ...tool,
  updatedAt: isoMoment(tool.updatedAt),
})

/** A setting's moment arrives in PostgreSQL's text form too (`changed_at::text`). */
const withIsoChange = <T extends { changedAt: string }>(setting: T): T => ({
  ...setting,
  changedAt: isoMoment(setting.changedAt),
})

/**
 * A failure as an `ApiError`; while the service runs other code than this app (api-version.ts),
 * any failure but a signed-out session is `outdated`, as trying again does not help.
 */

/** The service refuses a change whose token does not match the session (security.ts). */
const csrfRefused = (error: unknown) =>
  toApiError(error).kind === 'forbidden' && toApiError(error).message === refusals.csrf

export function createHttpApi({
  baseUrl,
  personal,
  fetch,
  newKey = randomKey,
}: HttpApiOptions): ContextApi {
  const send = fetch ?? ((request, init) => globalThis.fetch(request, init))
  const link = new OpenAPILink<CallContext>(routes as unknown as AnyContractRouter, {
    url: baseUrl,
    headers: ({ context }) => context.headers ?? {},
    // Every answer names the contract the service speaks.
    fetch: async (request, init) => {
      const response = await send(request, init)
      noteServiceVersion(response.headers.get(API_VERSION_HEADER))
      return response
    },
  })
  const client: ContractRouterClient<Contract, CallContext> = createORPCClient(link)

  /**
   * A failure as an `ApiError`; while the service runs other code than this app (api-version.ts),
   * any failure but a signed-out session is `outdated`, as trying again does not help.
   */
  function failure(error: unknown): ApiError {
    const failed = toApiError(error)
    const side = outdatedSide()
    return side && failed.kind !== 'signed-out'
      ? new ApiError('outdated', updateAdvice(side), { status: failed.status })
      : failed
  }

  /** The token of the latest session read; every change sends it. */
  let csrfToken: string | undefined
  /** Retry keys of changes that have not had a final answer yet, by operation and input. */
  const pendingKeys = new Map<string, string>()

  async function session() {
    const current = await client.auth.session()
    csrfToken = current.csrfToken
    return current
  }

  /** A read: every failure becomes an `ApiError`. */
  async function read<T>(call: () => Promise<T>): Promise<T> {
    try {
      return await call()
    } catch (error) {
      throw failure(error)
    }
  }

  /** Resolves to null when the service answers 404, as the mock does for an unknown id. */
  async function orNull<T>(call: () => Promise<T>): Promise<T | null> {
    try {
      return await read(call)
    } catch (error) {
      if (toApiError(error).kind === 'not-found') return null
      throw error
    }
  }

  /**
   * A change. The retry key is kept for the same operation and input until the service answers
   * with a result or a refusal; after no answer (`unavailable`) the next identical call reuses it.
   */
  async function write<T>(
    operation: string,
    input: unknown,
    call: (context: { context: CallContext }) => Promise<T>,
  ): Promise<T> {
    const id = `${operation} ${canonicalJson(JSON.parse(JSON.stringify(input ?? null)))}`
    const key = pendingKeys.get(id) ?? newKey()
    pendingKeys.set(id, key)
    const send = (token: string) =>
      call({ context: { headers: { 'x-heed-csrf': token, 'idempotency-key': key } } })
    try {
      let result: T
      try {
        result = await send(csrfToken ?? (await session()).csrfToken)
      } catch (error) {
        if (!csrfRefused(error)) throw error
        result = await send((await session()).csrfToken)
      }
      pendingKeys.delete(id)
      return result
    } catch (error) {
      if (!toApiError(error).retryable) pendingKeys.delete(id)
      throw failure(error)
    }
  }

  return {
    listItems: (params = {}) => read(() => client.items.list(params)),
    getItem: (id) => orNull(() => client.items.get({ id })),
    getItemLinks: (id) => orNull(() => client.items.links({ id })),
    listLibrary: () => read(() => client.library.index()),
    getLibraryFreshness: (params = {}) => read(() => client.library.freshness(params)),
    getItemHistory: async (id) => (await orNull(() => client.items.history({ id }))) ?? [],
    getServedReviews: (ids) =>
      ids.length ? read(() => client.library.reviews({ ids: [...ids] })) : Promise.resolve([]),
    listAreas: () => read(() => client.areas.list()),
    listPeople: () => read(() => client.people.list()),
    getVocabulary: () => read(() => client.vocabulary.get()),
    searchScope: (input) => read(() => client.vocabulary.search(input)),
    // A read sent as POST (many keys would not fit an address), so it carries the change token,
    // as the preview does.
    describeScope: (keys) =>
      write('vocabulary.describe', { keys }, (options) =>
        client.vocabulary.describe({ keys }, options),
      ),
    listCatalogue: () => read(() => client.catalogue.list()),
    getCatalogueTerm: (kind, id) => orNull(() => client.catalogue.get({ kind, id })),
    getSession: () => read(session),
    signOut: async () => {
      await write('auth.signOut', null, (options) => client.auth.signOut(undefined, options))
      csrfToken = undefined
    },
    listSignInPeople: () => read(() => client.auth.people()),
    // The local sign-in carries its own fixed header instead of a session's token, which it
    // does not have yet; the answer is the new session and its token.
    signIn: async (email) => {
      const signedIn = await read(() =>
        client.auth.signIn({ email }, { context: { headers: { 'x-heed-csrf': 'dev-sign-in' } } }),
      )
      csrfToken = signedIn.csrfToken
      return signedIn
    },
    getConnectRequest: (id) => orNull(() => client.connections.request({ id })),
    decideConnectRequest: (input) =>
      write('connections.decide', input, (options) => client.connections.decide(input, options)),
    listConnections: () => read(() => client.connections.list()),
    disconnectApp: (input) =>
      write('connections.disconnect', input, (options) =>
        client.connections.disconnect(input, options),
      ),
    listFavorites: () => Promise.resolve(personal.listFavorites()),
    setFavorite: (id, favorite) => Promise.resolve(personal.setFavorite(id, favorite)),
    listRecent: () => Promise.resolve(personal.listRecent()),
    recordVisit: (id) => Promise.resolve(personal.recordVisit(id)),

    listProposals: (params = {}) => read(() => client.proposals.list(params)),
    getProposal: (id) => orNull(() => client.proposals.get({ id })),
    previewProposal: (input) =>
      write('proposals.preview', input, (options) => client.proposals.preview(input, options)),
    getProposalOverlap: (id) => read(() => client.proposals.overlap({ id })),
    createProposal: (input) =>
      write('proposals.create', input, (options) => client.proposals.create(input, options)),
    saveDraft: (input) =>
      write('proposals.saveDraft', input, (options) => client.proposals.saveDraft(input, options)),
    submitProposal: (input) =>
      write('proposals.submit', input, (options) => client.proposals.submit(input, options)),
    withdrawProposal: (input) =>
      write('proposals.withdraw', input, (options) => client.proposals.withdraw(input, options)),
    discardDraft: (input) =>
      write('proposals.discard', input, (options) => client.proposals.discard(input, options)),
    commentOnProposal: (input) =>
      write('proposals.comment', input, (options) => client.proposals.comment(input, options)),
    claimProposal: (input) =>
      write('proposals.claim', input, (options) => client.proposals.claim(input, options)),
    handOverProposal: (input) =>
      write('proposals.handOver', input, (options) => client.proposals.handOver(input, options)),
    listProposalEvents: async (id) => (await orNull(() => client.proposals.events({ id }))) ?? [],
    listProposalTests: (id) => read(() => client.proposals.tests({ id })),
    attachProposalTest: (input) =>
      write('proposals.attachTest', input, (options) =>
        client.proposals.attachTest(input, options),
      ),
    detachProposalTest: (input) =>
      write('proposals.detachTest', input, (options) =>
        client.proposals.detachTest(input, options),
      ),

    listReviewQueue: (params = {}) => read(() => client.review.queue(params)),
    getReview: (id) => orNull(() => client.review.get({ id })),
    runChecks: (id) =>
      write('review.runChecks', { id }, (options) => client.review.runChecks({ id }, options)),
    editReview: (input) =>
      write('review.edit', input, (options) => client.review.edit(input, options)),
    decide: (input) =>
      write('review.decide', input, (options) => client.review.decide(input, options)),
    // A read sent as POST (a page of selected proposals), so it carries the change token.
    planDecisions: (input) =>
      write('review.planDecisions', input, (options) =>
        client.review.planDecisions(input, options),
      ),
    decideMany: (input) =>
      write('review.decideMany', input, (options) => client.review.decideMany(input, options)),
    assignProposals: (input) =>
      write('review.assign', input, (options) => client.review.assign(input, options)),
    listTermCandidates: () => read(() => client.vocabulary.candidates()),
    proposeTerms: (input) =>
      write('vocabulary.proposeBatch', input, (options) =>
        client.vocabulary.proposeBatch(input, options),
      ),
    decideTermBatch: (input) =>
      write('vocabulary.decideBatch', input, (options) =>
        client.vocabulary.decideBatch(input, options),
      ),

    listEditions: (params = {}) => read(() => client.editions.list(params)),
    rollbackEdition: (input) =>
      write('editions.rollback', input, (options) => client.editions.rollback(input, options)),
    previewRollback: (label) => read(() => client.editions.rollbackPreview({ label })),
    diffEdition: (input) => read(() => client.editions.diff(input)),
    exportEdition: (label) => read(() => client.editions.export({ label })),
    compareEditions: (input = {}) => read(() => client.editions.compare(input)),
    compareEditionItem: (input) => read(() => client.editions.compareItem(input)),
    editionFeed: (input = {}) => read(() => client.editions.feed(input)),

    listStops: () => read(() => client.serving.stops()),
    setStop: (input) =>
      write('serving.setStop', input, (options) => client.serving.setStop(input, options)),

    retireItem: (input) =>
      write('review.retire', input, (options) => client.review.retire(input, options)),
    proposeRetirement: (input) =>
      write('review.proposeRetirement', input, (options) =>
        client.review.proposeRetirement(input, options),
      ),
    recheckItem: (input) =>
      write('review.recheck', input, (options) => client.review.recheck(input, options)),

    listBin: () => read(() => client.bin.list()),
    getBinItem: (id) => orNull(() => client.bin.get({ id })),
    // A POST, so it carries the session's token like a change, as the proposal preview does.
    previewBin: (input) =>
      write('bin.preview', input, (options) => client.bin.preview(input, options)),
    moveToBin: (input) => write('bin.move', input, (options) => client.bin.move(input, options)),
    // A POST, so it carries the session's token like a change, as the Bin's preview does.
    previewRescue: (input) =>
      write('bin.rescuePreview', input, (options) => client.bin.rescuePreview(input, options)),
    restoreFromBin: (input) =>
      write('bin.restore', input, (options) => client.bin.restore(input, options)),

    listGaps: (params = {}) => read(() => client.gaps.list(params)),
    getGap: (id) => orNull(() => client.gaps.get({ id })),
    setGapStatus: (input) =>
      write('gaps.setStatus', input, (options) => client.gaps.setStatus(input, options)),
    addGapNote: (input) =>
      write('gaps.addNote', input, (options) => client.gaps.addNote(input, options)),
    linkGapTest: (input) =>
      write('gaps.linkTest', input, (options) => client.gaps.linkTest(input, options)),
    unlinkGapTest: (input) =>
      write('gaps.unlinkTest', input, (options) => client.gaps.unlinkTest(input, options)),
    startDraftFromGap: (input) =>
      write('gaps.startDraft', input, (options) => client.gaps.startDraft(input, options)),
    reportGap: (input) =>
      write('gaps.report', input, (options) => client.gaps.report(input, options)),
    getTopicCounts: (params = {}) => read(() => client.topics.counts(params)),
    getWeeklyCalls: (params = {}) => read(() => client.topics.weekly(params)),
    getEvalRun: (id) => orNull(() => client.evals.runs.get({ id })),
    listTestQuestions: (params = {}) => read(() => client.evals.questions.list(params)),
    saveTestQuestion: (input) =>
      write('evals.questions.save', input, (options) =>
        client.evals.questions.save(input, options),
      ),
    setAsideTestQuestion: (input) =>
      write('evals.questions.setAside', input, (options) =>
        client.evals.questions.setAside(input, options),
      ),
    importTestQuestions: (input) =>
      write('evals.questions.import', input, (options) =>
        client.evals.questions.import(input, options),
      ),
    exportTestQuestions: (params = {}) => read(() => client.evals.questions.export(params)),
    listEvalRuns: (params = {}) => read(() => client.evals.runs.list(params)),
    estimateEvalRun: (params) => read(() => client.evals.runs.estimate(params)),
    startEvalRun: (input) =>
      write('evals.runs.start', input, (options) => client.evals.runs.start(input, options)),
    approveEvalRun: (input) =>
      write('evals.runs.approve', input, (options) => client.evals.runs.approve(input, options)),
    cancelEvalRun: (input) =>
      write('evals.runs.cancel', input, (options) => client.evals.runs.cancel(input, options)),
    resumeEvalRun: (input) =>
      write('evals.runs.resume', input, (options) => client.evals.runs.resume(input, options)),
    getEvalTranscript: (id) => orNull(() => client.evals.transcript({ id })),
    getRetrievalLatest: (params = {}) => read(() => client.evals.retrieval.latest(params)),
    getRetrievalEdition: (params) => read(() => client.evals.retrieval.edition(params)),
    getRetrievalTrend: (params = {}) => read(() => client.evals.retrieval.trend(params)),
    getQualityHistory: (params = {}) => read(() => client.quality.history(params)),
    compareRuns: (params) => read(() => client.quality.compare(params)),
    getFeedbackCounts: (params = {}) => read(() => client.quality.feedback(params)),
    getRatingCounts: (params = {}) => read(() => client.quality.ratings(params)),
    getAppFamilyCounts: (params = {}) => read(() => client.quality.apps(params)),
    getUpkeep: (params = {}) => read(() => client.quality.upkeep(params)),
    getUntested: (params = {}) => read(() => client.quality.untested(params)),
    getFixNext: (params = {}) => read(() => client.quality.fixNext(params)),
    compareQuestion: (params) => read(() => client.quality.compareQuestion(params)),
    getQuestionHistory: (params) => read(() => client.quality.questionHistory(params)),
    listTools: async () => (await read(() => client.tools.list())).map(withIsoMoment),
    setTool: async (input) =>
      withIsoMoment(await write('tools.set', input, (options) => client.tools.set(input, options))),
    listClients: () => read(() => client.clients.list()),
    saveClient: (input) =>
      write('clients.save', input, (options) => client.clients.save(input, options)),
    getTraffic: (params = {}) => read(() => client.traffic.summary(params)),
    listAiConnections: () => read(() => client.aiConnections.list()),
    disconnectAiConnection: (input) =>
      write('aiConnections.disconnect', input, (options) =>
        client.aiConnections.disconnect(input, options),
      ),
    disconnectPersonAiConnections: (input) =>
      write('aiConnections.disconnectPerson', input, (options) =>
        client.aiConnections.disconnectPerson(input, options),
      ),
    listSettings: async () => (await read(() => client.settings.list())).map(withIsoChange),
    getSettingHistory: async (key) =>
      (await read(() => client.settings.history({ key }))).map(withIsoChange),
    setSetting: async (input) =>
      withIsoChange(
        await write('settings.set', input, (options) => client.settings.set(input, options)),
      ),
    searchPeople: (params) => read(() => client.people.search(params)),
    getPersonSheet: (id) => orNull(() => client.people.sheet({ id })),
    listGrants: async () => {
      const grants = await read(() => client.roles.list())
      return {
        roles: grants.roles.map((grant) => ({ ...grant, since: isoMoment(grant.since) })),
        assignments: grants.assignments.map((grant) => ({
          ...grant,
          since: isoMoment(grant.since),
        })),
      }
    },
    applyGrants: (input) =>
      write('grants.apply', input, (options) => client.grants.apply(input, options)),
    getArea: (id) => orNull(() => client.areas.get({ id })),
    createArea: (input) =>
      write('areas.create', input, (options) => client.areas.create(input, options)),
    updateArea: (input) =>
      write('areas.update', input, (options) => client.areas.update(input, options)),
    describeArea: (input) =>
      write('areas.describe', input, (options) => client.areas.describe(input, options)),
    getAreaRemoval: (id) => orNull(() => client.areas.removal({ id })),
    removeArea: (input) =>
      write('areas.remove', input, (options) => client.areas.remove(input, options)),
    listArchivedAreas: () => read(() => client.areas.archived()),
    restoreArea: (input) =>
      write('areas.restore', input, (options) => client.areas.restore(input, options)),
    getOperations: () => read(() => client.operations.overview()),
    runJob: (input) =>
      write('operations.run', input, (options) => client.operations.run(input, options)),
    listSourceTypes: () => read(() => client.sources.types()),
    getSourceSettings: (id) => orNull(() => client.sources.get({ id })),
    addSource: (input) =>
      write('sources.add', input, (options) => client.sources.add(input, options)),
    updateSource: (input) =>
      write('sources.update', input, (options) => client.sources.update(input, options)),
    // A read sent as a POST, for the secrets it carries, so it carries the session's token too.
    testSource: (input) =>
      write('sources.test', input, (options) => client.sources.test(input, options)),
    searchAudit: (params = {}) => read(() => client.audit.search(params)),
    exportAudit: (params = {}) => read(() => client.audit.export(params)),
    verifyAudit: () => read(() => client.audit.verify()),
    importItems: (input) =>
      write('imports.items', input, (options) => client.imports.items(input, options)),
    getConnectInfo: () => read(() => client.connect.get()),
    // A read sent as a POST, for its scope, so it carries the session's token like a change.
    tryIt: (input) => write('tryIt.run', input, (options) => client.tryIt.run(input, options)),
    // The question goes in a POST body, never in an address (FR-602).
    readTryItQuestion: (input) =>
      write('tryIt.read', input, (options) => client.tryIt.read(input, options)),
    // Server-sent events over fetch. A turn changes nothing a retry could repeat (a draft is
    // saved only on a confirmation, which the service keys itself), so it carries the session's
    // token and no retry key.
    assistantChat: (input, { signal } = {}) =>
      read(async () => {
        const send = async (token: string) =>
          (await client.assistant.chat(input, {
            ...(signal ? { signal } : {}),
            context: { headers: { 'x-heed-csrf': token } },
          })) as AsyncIterable<UIMessageChunk>
        try {
          return await send(csrfToken ?? (await session()).csrfToken)
        } catch (error) {
          if (!csrfRefused(error)) throw error
          return send((await session()).csrfToken)
        }
      }),
    // The service keeps no retry key for a rating: it would tie the rating to the person (FR-712).
    rateAnswer: (input) =>
      write('assistant.rate', input, (options) => client.assistant.rate(input, options)),
    listInbox: (params = {}) => read(() => client.inbox.list(params)),
    markInboxRead: (input) =>
      write('inbox.markRead', input, (options) => client.inbox.markRead(input, options)),
    markAllInboxRead: () =>
      write('inbox.markAllRead', null, (options) => client.inbox.markAllRead(undefined, options)),
    archiveInbox: (input) =>
      write('inbox.archive', input, (options) => client.inbox.archive(input, options)),
    // Server-sent events over fetch, so a reconnect can name the last event it read.
    streamEvents: ({ lastEventId, signal }) =>
      read(() =>
        client.events.stream(undefined, {
          signal,
          context: { headers: lastEventId === undefined ? {} : { 'last-event-id': lastEventId } },
        }),
      ),
  }
}
